    struct config *config;
    struct config_line line;
    int indent_level = 0;
    const char *errmsg;

    if (size == 0)
        return 1;

    if (size > sizeof(static_data))
        size = sizeof(static_data);
    memcpy(static_data, data, size);
    static_data[size - 1] = '\0';

    LWAN_NO_DISCARD(str_find((char *)static_data, "foo/(%d+)(%a)(%d+)", sf,
