#define uchar(c)        ((unsigned char)(c)) /* macro to 'unsign' a char */
#define CAP_UNFINISHED  (-1)
#define CAP_POSITION    (-2)
#define L_ESC           '%'
#define SPECIALS        "^$*+?.([%-"

struct match_state {
        int matchdepth;         /* control for recursive depth (to avoid C
                                 * stack overflow) */
        int repetitioncounter;  /* control the repetition items */
        int maxcaptures;        /* configured capture limit */
        const char *src_init;   /* init of source string */
        const char *src_end;    /* end ('\0') of source string */
        const char *p_end;      /* end ('\0') of pattern */
        const char *error;      /* should be NULL */
        int level;              /* total number of captures (finished or
                                 * unfinished) */
        struct {
                const char *init;
                ptrdiff_t len;
        } capture[MAXCAPTURES];
};

/* recursive function */
static const char *match(struct match_state *, const char *, const char *);

static int
match_error(struct match_state *ms, const char *error)
{
        ms->error = ms->error == NULL ? error : ms->error;
        return (-1);
}

static int
check_capture(struct match_state *ms, int l)
{
        l -= '1';
        if (l < 0 || l >= ms->level || ms->capture[l].len == CAP_UNFINISHED)
                return match_error(ms, "invalid capture index");
        return (l);
}

static int
capture_to_close(struct match_state *ms)
{
        int level = ms->level;
        for (level--; level >= 0; level--)
                if (ms->capture[level].len == CAP_UNFINISHED)
                        return (level);
        return match_error(ms, "invalid pattern capture");
}

static const char *
classend(struct match_state *ms, const char *p)
{
        switch (*p++) {
        case L_ESC:
                if (p == ms->p_end)
                        match_error(ms,
                            "malformed pattern (ends with '%')");
                return p + 1;
        case '[':
                if (*p == '^')
                        p++;
                do {
                        /* look for a ']' */
                        if (p == ms->p_end) {
                                match_error(ms,
                                    "malformed pattern (missing ']')");
                                break;
                        }
                        if (*(p++) == L_ESC && p < ms->p_end) {
                                /* skip escapes (e.g. '%]') */
                                p++;
                        }
                } while (*p != ']');
                return p + 1;
        default:
                return p;
        }
}

static int
match_class(int c, int cl)
{
        int res;
        switch (tolower(cl)) {
        case 'a':
                res = isalpha(c);
                break;
        case 'c':
                res = iscntrl(c);
                break;
        case 'd':
                res = isdigit(c);
                break;
        case 'g':
                res = isgraph(c);
                break;
        case 'l':
                res = islower(c);
                break;
        case 'p':
                res = ispunct(c);
                break;
        case 's':
                res = isspace(c);
                break;
        case 'u':
                res = isupper(c);
                break;
        case 'w':
                res = isalnum(c);
                break;
        case 'x':
                res = isxdigit(c);
                break;
        default:
                return (cl == c);
        }
        return (islower(cl) ? res : !res);
}

static int
matchbracketclass(int c, const char *p, const char *ec)
{
        int sig = 1;
        if (*(p + 1) == '^') {
                sig = 0;
                /* skip the '^' */
                p++;
        }
        while (++p < ec) {
                if (*p == L_ESC) {
                        p++;
                        if (match_class(c, uchar(*p)))
                                return sig;
                } else if ((*(p + 1) == '-') && (p + 2 < ec)) {
                        p += 2;
                        if (uchar(*(p - 2)) <= c && c <= uchar(*p))
                                return sig;
                } else if (uchar(*p) == c)
                        return sig;
        }
        return !sig;
}

static int
singlematch(struct match_state *ms, const char *s, const char *p,
    const char *ep)
{
        if (s >= ms->src_end)
                return 0;
        else {
                int c = uchar(*s);
                switch (*p) {
                case '.':
                        /* matches any char */
                        return (1);
                case L_ESC:
                        return match_class(c, uchar(*(p + 1)));
                case '[':
                        return matchbracketclass(c, p, ep - 1);
                default:
                        return (uchar(*p) == c);
                }
        }
}

